SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsBatchResponse
{
    boolean success;
    str     errorCode;
    boolean registered;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

/// <summary>
/// True when this item and batch combination already has an InventBatch master record -
/// this device has seen it before, or another one has. False means the operator's scan is
/// the first time D365FO has heard of this batch, which is what the client uses to decide
/// whether to ask for a manufacturing and expiry date before the batch can be used.
/// </summary>
[DataMemberAttribute('Registered')]
public boolean parmRegistered(boolean _value = registered)
{
    registered = _value;
    return registered;
}
